#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_TOKENS 64

static void error(void) {
    puts("ERROR");
    exit(1);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        error();
    }
    int token_cnt = argc - 1;
    if (token_cnt > MAX_TOKENS) {
        error();
    }
    long stack[MAX_TOKENS];
    int top = 0;
    for (int i = 0; i < token_cnt; ++i) {
        char *tok = argv[i + 1];
        bool is_op = false;
        if (strlen(tok) == 1) {
            switch (tok[0]) {
                case '+': case '-': case '*': case '/':
                    is_op = true; break;
                default: break;
            }
        }
        if (is_op) {
            if (top < 2) error();
            long right = stack[--top];
            long left = stack[--top];
            long result;
            switch (tok[0]) {
                case '+': result = left + right; break;
                case '-': result = left - right; break;
                case '*': result = left * right; break;
                case '/':
                    if (right == 0) error();
                    result = left / right; break;
                default: error();
            }
            if (top >= MAX_TOKENS) error();
            stack[top++] = result;
        } else {
            char *endptr;
            long val = strtol(tok, &endptr, 10);
            if (endptr == tok) error();
            if (top >= MAX_TOKENS) error();
            stack[top++] = val;
        }
    }
    if (top != 1) error();
    printf("%ld\n", stack[0]);
    return 0;
}
